// Helper functions
export function getLocationsByUrl(url: string): PageData | undefined {
  const cleanUrl = url.replace(/^\/+|\/+$/g, "");
  return locationsData.pages.find(
    (page) =>
      page.url === url ||
      page.url === `/${url}` ||
      page.url.replace(/^\/+|\/+$/g, "") === cleanUrl,
  );
}

export function getLocationsByKeyword(keyword: string): PageData[] {
  return locationsData.pages.filter(
    (page) =>
      page.metadata.primaryKeyword === keyword ||
      page.metadata.secondaryKeywords.includes(keyword),
  );
}

export default locationsData;
